class _CalcError(Exception):
    pass


def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_expr() -> int:
        val = parse_term()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                val = val + rhs if op == "+" else val - rhs
            else:
                break
        return val

    def parse_term() -> int:
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                else:
                    if rhs == 0:
                        raise _CalcError
                    q = abs(val) // abs(rhs)
                    if (val < 0) ^ (rhs < 0):
                        q = -q
                    val = q if op == "/" else val - rhs * q
            else:
                break
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "-":
                neg = not neg
                pos += 1
            else:
                break
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        base = parse_primary()
        skip_spaces()
        if pos < n and expr[pos] == "^":
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise _CalcError
            return base ** exp
        return base

    def parse_primary() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            skip_spaces()
            pos += 1  # ')'
            return val
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    try:
        return parse_expr()
    except _CalcError:
        return "error"
